import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR80','Sovraccarico biomeccanico: strumenti aggiornati',[CL("Quale norma tecnica?","Seleziona una situazione, poi la norma tecnica di riferimento.",["UNI ISO 11228-1 · sollevamento","UNI ISO 11228-2 · traino e spinta","UNI ISO 11228-3 · movimenti ripetitivi","UNI ISO 11226 · posture statiche"],[
 ["Scarico di sacchi da 20 kg da un bancale",0,"Sollevamento e trasporto."],["Spinta di carrelli porta-teglie in un panificio",1,"Traino e spinta."],
 ["Confezionamento manuale di caramelle con cicli di 10 secondi",2,"Movimenti ripetitivi degli arti superiori."],["Controllo visivo con il collo flesso per lunghi periodi",3,"Posture di lavoro statiche."],
 ["Traino di un transpallet manuale carico",1,"Traino."],["Avvitatura ripetitiva in linea di montaggio",2,"Movimenti ripetitivi."]],
 "Sei situazioni di sovraccarico biomeccanico. Individua la norma tecnica di riferimento.","Allegato XXXIII D.lgs. 81/2008 · serie UNI ISO 11228 · UNI ISO 11226")])
EA(K,'ZR81','Traino, spinta e posture di lavoro',[LB("Laboratorio · Traino, spinta e posture in un ospedale","Valuti le attività di movimentazione del personale ausiliario di un ospedale.",[
  ["Attività 1","spinta di carrelli della biancheria fino a 250 kg per corridoi con rampe"],["Attività 2","traino di carrelli dei pasti con ruote usurate"],["Attività 3","rifacimento dei letti con il busto flesso per lunghi periodi"],["Lamentele","dolori a spalle e schiena"]],[
  ("Quali fattori aumentano le forze di spinta e traino?",7,"Massa del carico, stato delle ruote e dei cuscinetti, pavimenti e pendenze delle rampe, frequenza e distanza dei tragitti, maniglie e altezza di presa, necessità di frenare in discesa.",["Ho elencato i fattori del carrello","Ho elencato i fattori del percorso"]),
  ("Come imposti la valutazione secondo la UNI ISO 11228-2?",7,"Misura delle forze iniziali e di mantenimento con un dinamometro sui percorsi reali, confronto con i valori di riferimento per la popolazione lavorativa, considerando frequenza e distanza.",["Ho previsto la misura delle forze","Ho previsto il confronto con i riferimenti"]),
  ("Come valuti le posture nel rifacimento dei letti?",7,"Con la UNI ISO 11226: angoli del tronco e durata delle posture statiche; il busto flesso a lungo è da considerare non accettabile oltre certi angoli e tempi. Misure: letti ad altezza regolabile e lavoro in coppia.",["Ho collegato la UNI ISO 11226","Ho proposto letti regolabili"]),
  ("Proponi un piano di miglioramento.",7,"Manutenzione programmata delle ruote; carrelli motorizzati per i carichi più pesanti; riduzione del carico per viaggio; rampe meno ripide o percorsi alternativi; letti regolabili; formazione sulle tecniche; nuova misura delle forze dopo gli interventi.",["Ho previsto interventi tecnici","Ho previsto interventi organizzativi","Ho previsto la verifica"])],
 "Nel laboratorio valuti traino, spinta e posture del personale ausiliario di un ospedale: fattori delle forze, metodo di valutazione, posture e piano di miglioramento. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 11228-2 · UNI ISO 11226 · Titolo VI D.lgs. 81/2008")])
EA(K,'ZR82','Esempio applicativo: il calcolo dell’indice di sollevamento',[LB("Laboratorio · Riprogettare la pallettizzazione","Riprogetti una postazione di pallettizzazione manuale di scatole da 14 kg.",[
  ["Situazione","prelievo dal nastro a 90 cm; deposito sul bancale da 10 a 150 cm di altezza; distanza orizzontale media 50 cm; torsione di 60°"],["Frequenza","3 sollevamenti al minuto per 2 ore"],["Calcolo attuale","indice di sollevamento LI ≈ 1,9 per le file più basse e più alte"]],[
  ("Quali fattori pesano di più sull’indice?",7,"La distanza orizzontale di 50 cm (HM = 0,5), l’altezza di deposito lontana da 75 cm nelle file estreme, la torsione di 60° (AM ≈ 0,81) e la frequenza elevata.",["Ho individuato HM e altezza","Ho considerato torsione e frequenza"]),
  ("Proponi tre modifiche della postazione.",7,"Tavola elevatrice e girevole sotto il bancale, per mantenere il piano di deposito tra 70 e 100 cm e ridurre la torsione; avvicinare il nastro al bancale per ridurre la distanza orizzontale; rotazione con mansioni leggere.",["Ho proposto la tavola elevatrice","Ho ridotto la distanza","Ho proposto la rotazione"]),
  ("Stima l’effetto delle modifiche sull’indice.",7,"Con distanza a 30 cm (HM ≈ 0,83), altezza vicino a 75 cm (VM ≈ 1), torsione eliminata (AM = 1), l’indice scende all’incirca a un terzo o meno del valore attuale, sotto 1, a parità di frequenza.",["Ho ricalcolato i fattori","Ho stimato un LI sotto 1"]),
  ("Come verifichi la soluzione?",6,"Nuovo calcolo dell’indice con i dati reali dopo gli interventi; osservazione delle posture; riscontro degli addetti e del medico competente.",["Ho previsto il ricalcolo","Ho coinvolto addetti e medico"])],
 "Nel laboratorio riprogetti una postazione di pallettizzazione con indice di sollevamento elevato: fattori critici, modifiche, stima del nuovo indice e verifica. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 11228-1 · Allegato XXXIII D.lgs. 81/2008")])
EA(K,'ZR83','Movimenti ripetitivi degli arti superiori: il metodo OCRA',[LB("Laboratorio · La check-list OCRA","Applichi la check-list OCRA a una postazione di assemblaggio di piccoli componenti.",[
  ["Turno","8 ore con 450 minuti di lavoro ripetitivo, moltiplicatore di durata 1"],["Punteggi parziali","recupero 4; frequenza 6; forza 2; postura 5; fattori complementari 1"],["Fasce","fino a 7,5 verde; 7,6-11 giallo; 11,1-14 rosso lieve; 14,1-22,5 rosso medio; oltre 22,5 viola"]],[
  ("Calcola il punteggio della check-list e la fascia.",6,"(4 + 6 + 2 + 5 + 1) × 1 = 18: fascia rossa media.",["Ho sommato i fattori","Ho applicato il moltiplicatore","Ho individuato la fascia"]),
  ("Su quali fattori intervieni prima?",7,"Frequenza e postura, che pesano di più: ridurre le azioni tecniche con attrezzi e alimentatori, migliorare la disposizione dei componenti per evitare posture estreme del polso e della spalla. Poi recupero, con pause meglio distribuite.",["Ho scelto i fattori dominanti","Ho proposto misure concrete"]),
  ("Stima il nuovo punteggio dopo gli interventi.",6,"Ad esempio frequenza da 6 a 3, postura da 5 a 2, recupero da 4 a 2: (2 + 3 + 2 + 2 + 1) × 1 = 10, fascia gialla. Servono ulteriori interventi o rotazioni per arrivare al verde.",["Ho ricalcolato il punteggio","Ho interpretato il risultato"]),
  ("Quali altre azioni prevedi?",6,"Sorveglianza sanitaria degli addetti; formazione; rotazione con postazioni non ripetitive; verifica con il metodo OCRA completo se necessario.",["Ho previsto sorveglianza e rotazione","Ho previsto un’analisi più approfondita"])],
 "Nel laboratorio applichi la check-list OCRA a una postazione di assemblaggio: punteggio, fattori su cui intervenire, nuovo punteggio e azioni. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 11228-3 · metodo OCRA")])
EA(K,'ZR84','Rischi psicosociali: dallo stress alla ISO 45003',[LB("Laboratorio · Gestire i rischi psicosociali con la ISO 45003","Applichi la ISO 45003 in un’impresa di servizi informatici con 120 dipendenti.",[
  ["Segnali","turnover del 22%, straordinari frequenti, lavoro da remoto senza regole sugli orari, conflitti tra team"],["Valutazione stress","effettuata quattro anni fa con esito «rischio basso»"]],[
  ("Quali fattori di rischio psicosociale individui?",7,"Carico e ritmi elevati; orari estesi e difficoltà di disconnessione nel lavoro da remoto; relazioni e conflitti tra gruppi; scarso riconoscimento; incertezza sui ruoli. Il turnover alto è un segnale coerente.",["Ho individuato carico e orari","Ho individuato relazioni e ruoli"]),
  ("Perché la valutazione di quattro anni fa non basta?",6,"Le condizioni sono cambiate, con lavoro da remoto e crescita; i segnali attuali contraddicono l’esito; la valutazione va aggiornata quando cambiano organizzazione e indicatori.",["Ho collegato il cambiamento organizzativo","Ho collegato gli indicatori"]),
  ("Quali misure organizzative proponi secondo la ISO 45003?",8,"Pianificazione dei carichi e delle priorità; regole su orari e diritto alla disconnessione; chiarezza dei ruoli; formazione dei responsabili alla gestione delle persone; canali di ascolto e supporto; partecipazione dei lavoratori nella definizione delle misure.",["Ho proposto misure su carichi e orari","Ho previsto formazione dei responsabili","Ho previsto partecipazione e supporto"],None,120),
  ("Come monitori i risultati?",6,"Indicatori come turnover, assenze, straordinari, segnalazioni; indagini periodiche sul benessere; riesame annuale con RSPP, medico competente e RLS.",["Ho proposto indicatori","Ho previsto il riesame"])],
 "Nel laboratorio applichi la ISO 45003 ai rischi psicosociali di un’impresa di servizi informatici: fattori, aggiornamento della valutazione, misure e monitoraggio. Confronta ogni risposta con la soluzione di riferimento.","UNI ISO 45003 · art. 28 D.lgs. 81/2008")])
EA(K,'ZR85','La valutazione approfondita: lo strumento indicatore INAIL',[LB("Laboratorio · La valutazione approfondita","Organizzi la valutazione approfondita dello stress in un call center dopo una valutazione preliminare con esito «rischio medio».",[
  ["Gruppi omogenei","operatori inbound, operatori outbound, team leader"],["Lavoratori","90"],["Clima","diffidenza verso i questionari"]],[
  ("Come organizzi la somministrazione del questionario strumento indicatore?",7,"Somministrazione anonima per gruppi omogenei, con un numero minimo di rispondenti per gruppo che tuteli l’anonimato; comunicazione preventiva degli scopi; coinvolgimento dell’RLS; tempi dedicati in orario di lavoro.",["Ho previsto anonimato e gruppi","Ho previsto comunicazione e RLS"]),
  ("Come affianchi il questionario con altri strumenti?",7,"Focus group per gruppo omogeneo, per approfondire i risultati e raccogliere proposte; confronto con gli indicatori oggettivi della valutazione preliminare.",["Ho previsto i focus group","Ho collegato gli indicatori"]),
  ("Come restituisci i risultati e trasformi in azioni?",7,"Restituzione ai lavoratori dei risultati aggregati; piano d’azione con misure, responsabili e tempi; verifica dell’efficacia con una nuova rilevazione.",["Ho previsto la restituzione","Ho previsto il piano d’azione e la verifica"])],
 "Nel laboratorio organizzi la valutazione approfondita dello stress lavoro-correlato in un call center: questionario, focus group, restituzione e azioni. Confronta ogni risposta con la soluzione di riferimento.","Metodologia INAIL per la valutazione dello stress lavoro-correlato")])
EA(K,'ZR86','Burnout, mobbing e straining',[SC("La segnalazione di mobbing","Un’impiegata segnala all’RSPP di essere isolata dai colleghi, esclusa dalle riunioni e assegnata a compiti inferiori da mesi.",[
 ("Come qualifichi la situazione in via preliminare?",[["Possibile mobbing o straining, da verificare: condotte vessatorie ripetute nel tempo o un’azione ostile con effetti duraturi",True,"Corretto: la qualificazione richiede accertamenti."],["Un normale conflitto, da ignorare",False,"Va approfondito."],["Mobbing certo",False,"Serve una verifica."]]),
 ("A chi indirizzi la lavoratrice e chi coinvolgi?",[["Medico competente per gli aspetti di salute, canali aziendali di segnalazione e la direzione per la verifica dei fatti",True,"Corretto."],["Solo ai colleghi",False,"Non è il canale corretto."],["A nessuno",False,"La segnalazione va gestita."]]),
 ("Che cosa aggiungi alla valutazione dei rischi?",[["I rischi di violenza e molestie e una procedura di prevenzione e gestione delle segnalazioni",True,"Corretto."],["Nulla",False,"Il caso evidenzia una lacuna."],["Un questionario una tantum",False,"Serve una procedura stabile."]])],
 "Le segnalazioni di mobbing vanno accolte, verificate e gestite con medico competente e canali dedicati, e la prevenzione entra nella valutazione dei rischi.","Una lavoratrice segnala isolamento e demansionamento. Gestisci la segnalazione.","Art. 28 D.lgs. 81/2008 · Convenzione OIL n. 190")])
EA(K,'ZR87','Aggressioni al personale: il caso della sanità e dei servizi al pubblico',[LB("Laboratorio · Prevenire le aggressioni in un pronto soccorso","Imposti le misure contro le aggressioni al personale di un pronto soccorso.",[
  ["Eventi","14 aggressioni verbali e 3 fisiche in un anno, soprattutto di notte e durante le attese lunghe"],["Ambiente","sala d’attesa affollata, triage esposto, nessun servizio di vigilanza notturno"],["Personale","infermieri e medici, molti neoassunti"]],[
  ("Quali fattori di rischio individui?",7,"Attese lunghe senza informazioni; affollamento; turni notturni con poco personale; postazione di triage esposta; assenza di vigilanza; inesperienza nella gestione dei conflitti.",["Ho individuato fattori organizzativi","Ho individuato fattori ambientali"]),
  ("Proponi misure strutturali.",7,"Postazione di triage protetta con via di fuga; pulsanti di allarme collegati; videosorveglianza; vigilanza nelle fasce critiche; sala d’attesa con informazioni sui tempi.",["Ho proposto protezioni e allarmi","Ho proposto vigilanza e informazione"]),
  ("Proponi misure organizzative e formative.",7,"Comunicazione periodica dei tempi di attesa; personale adeguato di notte; formazione alla gestione dei conflitti e alla de-escalation; procedura di segnalazione e supporto alle vittime.",["Ho previsto formazione specifica","Ho previsto segnalazione e supporto"]),
  ("Come misuri l’efficacia?",6,"Registro degli episodi per gravità e fascia oraria; confronto prima e dopo; questionari sul senso di sicurezza del personale; riesame con RLS e medico competente.",["Ho previsto il registro","Ho previsto il confronto prima e dopo"])],
 "Nel laboratorio imposti la prevenzione delle aggressioni in un pronto soccorso: fattori di rischio, misure strutturali, organizzative e formative, indicatori di efficacia. Confronta ogni risposta con la soluzione di riferimento.","Art. 28 D.lgs. 81/2008 · Raccomandazione ministeriale n. 8")])
EA(K,'ZR88','Le tutele penali per il personale sanitario',[SC("L’aggressione all’infermiere","Un familiare di un paziente colpisce un infermiere durante il turno, causando lesioni guaribili in 10 giorni.",[
 ("Che cosa prevede la legge per le lesioni al personale sanitario?",[["Pene aggravate e procedibilità d’ufficio per le lesioni al personale sanitario e socio-sanitario nell’esercizio delle funzioni",True,"Corretto: L. 113/2020."],["Nessuna tutela specifica",False,"La legge prevede tutele specifiche."],["Solo una sanzione amministrativa",False,"Sono reati."]]),
 ("Che cosa fa la struttura dopo l’evento?",[["Supporto all’infermiere, registrazione dell’evento, analisi delle cause e aggiornamento delle misure",True,"Corretto."],["Nulla, è un fatto penale",False,"Riguarda anche la prevenzione."],["Sposta l’infermiere senza analisi",False,"Non risolve le cause."]]),
 ("L’evento è un infortunio sul lavoro?",[["Sì: va denunciato all’INAIL se la prognosi supera tre giorni",True,"Corretto."],["No, è stato causato da terzi",False,"È comunque in occasione di lavoro."],["Solo se c’è una condanna",False,"Non serve."]])],
 "Le aggressioni al personale sanitario sono reati aggravati e procedibili d’ufficio, ma anche infortuni sul lavoro da denunciare e analizzare per prevenire.","Un infermiere aggredito in reparto. Gestisci le conseguenze.","L. 113/2020 · D.P.R. 1124/1965")])
EA(K,'ZR89','Rischi emergenti',[CL("Rischio emergente o tradizionale?","Seleziona un rischio, poi la colonna.",["Emergente","Tradizionale ben noto"],[
 ["Interazione con robot collaborativi",0,"Nuova tecnologia."],["Rumore di una pressa",1,"Rischio noto e normato da tempo."],
 ["Gestione algoritmica del lavoro e controllo digitale",0,"Fattore psicosociale emergente."],["Caduta da una scala",1,"Rischio tradizionale."],
 ["Ondate di calore più frequenti per il cambiamento climatico",0,"Rischio emergente o in crescita."],["Nanomateriali in produzione",0,"Rischio emergente."]],
 "Sei rischi. Distingui quelli emergenti da quelli tradizionali ben noti.","EU-OSHA · art. 28 D.lgs. 81/2008")])
EA(K,'ZR90','Alcol e sostanze: quadro normativo e controlli',[LB("Laboratorio · La procedura alcol e sostanze","Prepari la procedura aziendale su alcol e sostanze per un’impresa di trasporti e logistica.",[
  ["Mansioni","autisti di mezzi pesanti con patente C; carrellisti; impiegati"],["Situazione","nessuna procedura; un episodio sospetto il mese scorso"]],[
  ("Quali mansioni rientrano nei controlli e quali?",7,"Autisti con patente C e carrellisti sono tra le mansioni a rischio per l’alcol; gli autisti con patente C rientrano anche negli accertamenti per sostanze stupefacenti. Gli impiegati non rientrano. I controlli sono svolti dal medico competente secondo le procedure previste.",["Ho individuato le mansioni a rischio","Ho indicato il medico competente"]),
  ("Che cosa prevede la procedura in caso di sospetta alterazione?",7,"Il preposto allontana il lavoratore dalla mansione a rischio, informa il datore di lavoro e il medico competente, documenta i fatti in modo oggettivo; il lavoratore non riprende la mansione fino alla valutazione.",["Ho previsto l’allontanamento","Ho previsto la documentazione oggettiva"]),
  ("Quali misure di prevenzione e supporto aggiungi?",7,"Divieto di somministrazione e assunzione di alcol per le mansioni a rischio; informazione e formazione; accesso a percorsi di supporto e riabilitazione; riservatezza delle informazioni sanitarie.",["Ho previsto divieti e formazione","Ho previsto supporto e riservatezza"])],
 "Nel laboratorio prepari la procedura su alcol e sostanze per un’impresa di trasporti: mansioni e controlli, gestione della sospetta alterazione, prevenzione e supporto. Confronta ogni risposta con la soluzione di riferimento.","L. 125/2001 · Intesa Stato-Regioni 16 marzo 2006 · art. 41 D.lgs. 81/2008")])
EA(K,'ZR91','Attività su strada: segnaletica temporanea e formazione',[LB("Laboratorio · Il cantiere stradale","Organizzi un intervento di manutenzione del verde lungo una strada extraurbana con traffico.",[
  ["Intervento","sfalcio delle banchine per 3 km, di giorno"],["Squadra","4 operai e un preposto"],["Situazione","nessuna formazione specifica sulla segnaletica temporanea"]],[
  ("Quale formazione serve?",6,"Il corso specifico per l’attività in presenza di traffico veicolare: per i lavoratori 8 ore con moduli giuridico, tecnico e pratico; per i preposti 12 ore; aggiornamento periodico.",["Ho indicato i corsi per lavoratori e preposti","Ho ricordato l’aggiornamento"]),
  ("Come posizioni la segnaletica?",7,"Secondo gli schemi segnaletici del disciplinare: segnali di preavviso, di pericolo e di limitazione a distanze adeguate alla velocità della strada; cantiere mobile con veicolo segnalatore; installazione e rimozione seguendo la sequenza prevista.",["Ho previsto preavviso e pericolo","Ho previsto il veicolo segnalatore","Ho previsto la sequenza"]),
  ("Quali DPI e regole operative?",6,"Indumenti ad alta visibilità di classe adeguata; operare sempre rivolti al traffico quando possibile; comunicazione tra operatori; sospensione in caso di scarsa visibilità.",["Ho previsto l’alta visibilità","Ho previsto regole operative"]),
  ("Che cosa fa il preposto?",6,"Verifica la segnaletica prima dell’inizio e durante i lavori, vigila sul rispetto delle procedure, interrompe l’attività in caso di pericolo e coordina la rimozione finale.",["Ho descritto verifica e vigilanza","Ho previsto l’interruzione"])],
 "Nel laboratorio organizzi un intervento lungo una strada con traffico: formazione, segnaletica, DPI e ruolo del preposto. Confronta ogni risposta con la soluzione di riferimento.","D.I. 22 gennaio 2019 · Codice della strada · art. 161 D.lgs. 81/2008")])
EA(K,'ZR92','Nuove tecnologie: robot collaborativi, automazione e intelligenza artificiale',[LB("Laboratorio · Il robot collaborativo in linea","Valuti l’introduzione di un robot collaborativo in una linea di avvitatura.",[
  ["Applicazione","robot che avvita componenti mentre l’operatore inserisce i pezzi nella stessa area"],["Modalità","limitazione di forza e potenza"],["Preoccupazioni","contatti con le mani, ritmo imposto, monitoraggio delle prestazioni con software"]],[
  ("Quali rischi meccanici valuti?",7,"Contatti e schiacciamenti delle mani tra utensile e pezzo; urti con parti del robot; rischi dell’utensile. La valutazione dell’applicazione, non solo del robot, verifica forze e pressioni rispetto ai limiti per le parti del corpo.",["Ho considerato l’applicazione completa","Ho considerato forze e pressioni"]),
  ("Quali rischi organizzativi e psicosociali?",7,"Ritmo dettato dalla macchina; riduzione dell’autonomia; monitoraggio delle prestazioni con possibili implicazioni di controllo; carico cognitivo; necessità di competenze nuove.",["Ho considerato ritmo e autonomia","Ho considerato il monitoraggio"]),
  ("Quali misure e quali riferimenti?",7,"Valutazione secondo le norme sulla sicurezza dei robot industriali e dell’applicazione collaborativa; dispositivi di arresto; formazione; coinvolgimento dell’RLS; regole sull’uso dei dati delle prestazioni nel rispetto delle norme sui controlli a distanza; verifica del regolamento macchine per i sistemi con funzioni evolutive.",["Ho citato norme e formazione","Ho considerato l’uso dei dati"])],
 "Nel laboratorio valuti l’introduzione di un robot collaborativo: rischi meccanici, organizzativi e psicosociali, misure e riferimenti. Confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 10218 · Reg. (UE) 2023/1230 · art. 4 L. 300/1970")])
EA(K,'ZR93','Lavoro agile, telelavoro e lavoro da remoto',[SC("Telelavoro o lavoro agile?","Un’impresa vuole far lavorare un gruppo di impiegati sempre da casa, con postazione fornita dall’azienda e orari fissi.",[
 ("Di quale modalità si tratta?",[["Telelavoro: postazione fissa fuori dall’azienda, con applicazione delle norme sui videoterminali",True,"Corretto: art. 3, comma 10."],["Lavoro agile",False,"Il lavoro agile non ha una postazione fissa e alterna sedi."],["Lavoro autonomo",False,"Restano dipendenti."]]),
 ("Quali obblighi ha il datore di lavoro?",[["Verificare la postazione, anche accedendo con preavviso e consenso, e applicare il Titolo VII sui videoterminali",True,"Corretto."],["Nessuno, la casa è del lavoratore",False,"Gli obblighi restano."],["Solo inviare un opuscolo",False,"Non basta."]]),
 ("Che cosa cambia per l’isolamento sociale?",[["Va valutato e mitigato con contatti regolari con i colleghi e informazioni aziendali",True,"Corretto."],["Non è un rischio",False,"È un fattore da considerare."],["Si risolve con più straordinari",False,"No."]])],
 "Il telelavoro ha una postazione fissa e porta con sé gli obblighi sui videoterminali; il lavoro agile ha regole proprie: distinguere le modalità evita errori di valutazione.","Una modalità di lavoro da casa. Qualificala e applica gli obblighi.","Art. 3, c. 10, D.lgs. 81/2008 · L. 81/2017")])
EA(K,'ZR94','Esercitazione 3 · Affermazioni vere o false',[AP("Rischi ergonomici, psicosociali ed emergenti nella tua realtà","Verifica lo stato delle valutazioni.",["Valutazione della movimentazione dei carichi aggiornata","Valutazione dei movimenti ripetitivi","Valutazione dello stress negli ultimi tre anni","Procedura contro violenza e molestie","Procedura alcol e sostanze","Regole per lavoro agile e disconnessione","Valutazione delle nuove tecnologie introdotte"],"La valutazione da aggiornare per prima e perché","Es.: stress lavoro-correlato dopo la riorganizzazione dei turni",
  "Verifica lo stato delle valutazioni dei rischi ergonomici, psicosociali ed emergenti e indica quella da aggiornare per prima.",3)])
